source='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def exposed(r, c, color):
        return all(not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] in (background, color)
                   for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)))

    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == background:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                run = [(r, c)]
                nr, nc = r + dr, c + dc
                while 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    run.append((nr, nc))
                    nr, nc = nr + dr, nc + dc
                if len(run) < 2:
                    continue
                if exposed(r, c, color):
                    rr, cc = r - dr, c - dc
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == background:
                        out[rr][cc] = color
                        rr, cc = rr - dr, cc - dc
                er, ec = run[-1]
                if exposed(er, ec, color):
                    rr, cc = er + dr, ec + dc
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == background:
                        out[rr][cc] = color
                        rr, cc = rr + dr, cc + dc
    return out
'''
